import {
  bucketize,
  CliParseError,
  formatCliError,
  formatCliHelp,
  formatPythonBucketMap,
  formatPythonIntTraceback,
  getProgramName,
  parseArguments,
  parsePythonInt,
  PythonIntParseError,
} from './lib/index.mjs';

const programName = getProgramName(process.argv[1]);

try {
