export function formatPythonStringLiteral(value) {
  let escaped = '';

  for (const char of value) {
    switch (char) {
      case '\\':
        escaped += '\\\\';
        break;
      case '\'':
        escaped += '\\\'';
        break;
      case '\n':
        escaped += '\\n';
        break;
      case '\r':
        escaped += '\\r';
        break;
      case '\t':
        escaped += '\\t';
        break;
      case '\b':
        escaped += '\\b';
        break;
      case '\f':
        escaped += '\\f';
        break;
      case '\v':
        escaped += '\\x0b';
        break;
      default: {
        const code = char.codePointAt(0);

        if (code !== undefined && (code < 0x20 || code === 0x7f)) {
          escaped += `\\x${code.toString(16).padStart(2, '0')}`;
        } else {
          escaped += char;
        }
      }
    }
  }

  return `'${escaped}'`;
}

export function formatPythonBucketMap(bucketMap) {
  const parts = [];

  for (const [key, values] of bucketMap.entries()) {
    const renderedKey = key ? 'True' : 'False';
    const renderedValues = values.map((value) => value.toString()).join(', ');
    parts.push(`${renderedKey}: [${renderedValues}]`);
  }

  return `{${parts.join(', ')}}`;
}

export function formatCliHelp(programName) {
  return `usage: ${programName} [-h] --a A\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Comma-separated numbers\n`;
}

export function formatCliError(programName, message) {
  return `usage: ${programName} [-h] --a A\n${programName}: error: ${message}\n`;
}

export function formatPythonIntTraceback(message, pid) {
  return `Traceback (most recent call last):\n  File "test5.py", line 8, in <module>\nValueError: ${message}\n[PYI-${pid}:ERROR] Failed to execute script 'test5' due to unhandled exception!\n`;
}

